const format = function meetingList({ events, timeZone }) {
  const escape = (text) => String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  let text = '<b>Your meetings today are:</b>\n';
  for (const event of events) {
    let time;
    if (event.start?.date) time = 'All day';
    else {
      const start = new Date(event.start?.dateTime);
      if (!Number.isFinite(start.getTime())) throw new Error('A calendar event has no valid start time');
      time = new Intl.DateTimeFormat('fa-IR', { hour: 'numeric', minute: 'numeric', timeZone: event.start.timeZone || timeZone }).format(start);
    }
    const guests = event.attendees?.length ? event.attendees.map(({ email }) => email).join(', ') : 'No guests';
    text += '\n• ' + escape(event.summary || '(Untitled event)') + ' | ' + escape(time) + '\n  Guests: ' + escape(guests) + '\n';
  }
  if (text.length > 4096) throw new Error('The meeting list exceeds Telegram’s 4096-character message limit');
  return { text, count: events.length };
}

return [{json:format({events:$input.all().map(item=>item.json),timeZone:$now.zoneName}),pairedItem:$input.all().map((_,item)=>({item}))}];

const window = function localDayWindow({ timeZone }) {
  const now = Date.now();
  const formatter = new Intl.DateTimeFormat('en-CA-u-ca-iso8601', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' });
  const key = (instant) => {
    const parts = Object.fromEntries(formatter.formatToParts(new Date(instant)).map(({ type, value }) => [type, value]));
    return parts.year + '-' + parts.month + '-' + parts.day;
  };
  const date = key(now);
  const [year, month, day] = date.split('-').map(Number);
  const calendarDate = Date.UTC(year, month - 1, day);
  const nextDate = new Date(calendarDate + 86400000).toISOString().slice(0, 10);
  const boundary = (dateKey, center) => {
    let low = center - 36 * 3600000, high = center + 36 * 3600000;
    while (low < high) {
      const middle = Math.floor((low + high) / 2);
      if (key(middle) < dateKey) low = middle + 1;
      else high = middle;
    }
    return new Date(low).toISOString();
  };
  return { timeMin: boundary(date, calendarDate), timeMax: boundary(nextDate, calendarDate + 86400000), timeZone };
}

return [{json:window({timeZone:$now.zoneName}),pairedItem:{item:0}}];
